package com.example.tasks.domain;

import java.time.Instant;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.Objects;
import java.util.Set;
import java.util.UUID;

/**
 * An immutable history entry (data-model.md, ActivityEvent). {@code changes} is keyed by the
 * migration's allowlisted snake_case field names and holds rendered previous and new values,
 * never tokens, storage keys or stack traces.
 *
 * @param id generated by the database; null until appended
 * @param actorId the acting user, or null for the system actor
 * @param deadlineRequestId the request a request transition refers to, otherwise null
 */
public record ActivityEvent(
        Long id,
        Long taskId,
        UUID actorId,
        String type,
        Instant occurredAt,
        Map<String, Change> changes,
        Long deadlineRequestId) {

    public static final String TASK_CREATED = "task_created";
    public static final String TASK_EDITED = "task_edited";
    public static final String TASK_REASSIGNED = "task_reassigned";
    public static final String STATUS_CHANGED = "status_changed";
    public static final String TASK_REOPENED = "task_reopened";
    public static final String TASK_CANCELLED = "task_cancelled";
    public static final String REQUEST_SUBMITTED = "deadline_request_submitted";
    public static final String REQUEST_APPROVED = "deadline_request_approved";
    public static final String REQUEST_DECLINED = "deadline_request_declined";
    public static final String REQUEST_WITHDRAWN = "deadline_request_withdrawn";
    public static final String REQUEST_SUPERSEDED = "deadline_request_superseded";

    public static final Set<String> TYPES = Set.of(TASK_CREATED, TASK_EDITED, TASK_REASSIGNED, STATUS_CHANGED,
            TASK_REOPENED, TASK_CANCELLED, REQUEST_SUBMITTED, REQUEST_APPROVED, REQUEST_DECLINED, REQUEST_WITHDRAWN,
            REQUEST_SUPERSEDED);

    /** Field names allowed in {@code changes}; mirrors task.activity_changes_allowlisted. */
    public static final Set<String> FIELDS = Set.of("title", "description", "priority", "assignee_id", "due_at",
            "due_time_zone", "status", "blocked_reason", "cancellation_reason", "completed_at", "proposed_due_at",
            "proposed_time_zone", "reason", "state", "resolution_cause");

    public ActivityEvent {
        Objects.requireNonNull(taskId, "taskId");
        Objects.requireNonNull(type, "type");
        Objects.requireNonNull(occurredAt, "occurredAt");
        Task.require(TYPES.contains(type), "unknown activity type " + type);
        Task.require(FIELDS.containsAll(changes.keySet()), "changes contain a field outside the allowlist");
        changes = Collections.unmodifiableMap(new LinkedHashMap<>(changes));
    }

    public static ActivityEvent of(long taskId, UUID actorId, String type, Instant at, Map<String, Change> changes) {
        return new ActivityEvent(null, taskId, actorId, type, at, changes, null);
    }

    public ActivityEvent withId(long newId) {
        return new ActivityEvent(newId, taskId, actorId, type, occurredAt, changes, deadlineRequestId);
    }

    public ActivityEvent forRequest(long requestId) {
        return new ActivityEvent(id, taskId, actorId, type, occurredAt, changes, requestId);
    }

    /** A rendered previous and new value; either may be null (absent before or after). */
    public record Change(String previous, String next) {
    }
}
